<?php $defaults=$case?$case['proposal']:null;$type=$values['type']??($defaults['type']??'amount');$amount=$values['amount']??\Tivoli\Domain\Stay\StayRules::decimal($defaults['after']['amount']??$source['position']['amount']);$method=$values['method']??($defaults['after']['method']??$source['position']['method']);$reference=$values['reference']??($defaults['after']['reference']??$source['position']['reference']); ?>
<section class="card"><h2><?=$case?'Revise Returned Request':'Request A Recording Correction'?></h2><p>Correct the verified recorded facts. Original entries remain; this does not move, collect or refund money.</p>
<form method="post" enctype="multipart/form-data" id="cc-request" data-confirm="Submit this recording correction for owner review? No financial adjustment is posted yet." data-amount="<?=$source['position']['amount']?>" data-balance="<?=$source['bill']['balance']?>" data-refunded="<?=$source['refunded']?>" data-method="<?=access_h($source['position']['method'])?>" data-reference="<?=access_h($source['position']['reference'])?>" data-wallet-verified="<?=$source['wallet_verified']??0?>">
<?php cc_fields($case?'revise':'request');?><label>What Needs Correcting? *<select name="type"><?php foreach(['amount'=>'Correct Recorded Amount','method'=>'Correct Method / Reference','duplicate'=>'Duplicate Recorded Receipt','refund'=>'Money Was Actually Returned'] as $v=>$label):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=access_h($label)?></option><?php endforeach?></select></label>
<div data-cc-fields="amount"><label>Correct Total Receipt (GHS) *<input name="amount" inputmode="decimal" value="<?=access_h($amount)?>" maxlength="24" <?=$type==='amount'?'required':'disabled'?>><small>Enter the total actually received, not the difference.</small></label></div>
<div data-cc-fields="method" class="cc-grid"><label>Actual Method *<select name="method" <?=$type==='method'?'':'disabled'?>><option value="cash" <?=$method==='cash'?'selected':''?>>Cash</option><option value="momo" <?=$method==='momo'?'selected':''?>>MoMo</option></select></label><label>Actual Reference<input name="reference" value="<?=access_h($reference)?>" maxlength="120" <?=$type==='method'?'':'disabled'?>></label></div>
<div data-cc-fields="duplicate"><label>Keep This Evidenced Receipt *<select name="keeper_id" <?=$type==='duplicate'?'required':'disabled'?>><option value="">Choose Actual Collection</option><?php foreach($source['keepers'] as $keeper):?><option value="<?=(int)$keeper['id']?>" <?=($values['keeper_id']??(string)($defaults['keeper_id']??''))===(string)$keeper['id']?'selected':''?>>Receipt #<?=(int)$keeper['id']?> · <?=access_h(cc_money($keeper['position']['amount']).' · '.strtoupper($keeper['position']['method']))?></option><?php endforeach?></select></label><p>Evidence must support one actual collection for the same stay. Both original rows and references remain retained.</p></div>
<div data-cc-fields="refund"><p class="cc-warning">Actual money returned is a separate refund. A duplicated or overstated record is not proof that the guest paid extra money.</p><?php if($owner&&$source['bill']['balance']<0):?><a href="<?=access_h(access_url('occupancy.php?booking_id='.(int)$source['booking']['id'].'&form=refund'))?>#stay-action">Open Existing Guest Refund Workflow</a><?php else:?><p>Eugene must verify any real overpayment and record an already executed refund through the guest account.</p><?php endif?></div>
<?php if($source['dependencies']):?><section data-cc-linked><h3>Reconcile Linked Money</h3><p>Existing deposits, handovers and verified wallet credits cannot be reduced or counted again. Select an existing supporting receipt only when the preview needs it.</p>
<div data-cc-cash-support><label>Existing Cash Receipt Funding The Difference<select name="cash_support_id"><option value="">None / Not Needed</option><?php foreach($source['funding_candidates']??[] as $candidate):if($candidate['position']['method']!=='cash')continue;?><option value="<?=(int)$candidate['id']?>" <?=($values['cash_support_id']??($defaults['reconciliation']['inputs']['cash_support_id']??''))===(string)$candidate['id']?'selected':''?>>Receipt #<?=(int)$candidate['id']?> · <?=access_h(cc_money($candidate['position']['amount']))?></option><?php endforeach?></select></label><p>Must be unused cash from the same collector, already received before the linked cash movement. Duplicate corrections use the retained actual collection.</p></div>
<div data-cc-wallet-support><label>Existing MoMo Receipt Owning Verified Excess<select name="wallet_support_id"><option value="">None / Not Needed</option><?php foreach($source['funding_candidates']??[] as $candidate):if($candidate['position']['method']!=='momo')continue;?><option value="<?=(int)$candidate['id']?>" <?=($values['wallet_support_id']??($defaults['reconciliation']['inputs']['wallet_support_id']??''))===(string)$candidate['id']?'selected':''?>>Receipt #<?=(int)$candidate['id']?> · <?=access_h(cc_money($candidate['position']['amount']))?></option><?php endforeach?></select></label><p>Only independently verified existing proof can be allocated. Disputed proof and insufficient matching capacity stay blocked.</p></div>
<?php cc_check('reconcile','I reviewed the linked money records and any supporting receipt. This does not create or move money.');?></section><?php endif?>
<?php cc_text('Reason','reason',true,$defaults['reason']??'');?><label>Supporting Evidence (Optional)<input type="file" name="evidence" accept=".pdf,.jpg,.jpeg,.png"><small>PDF, JPEG or PNG · Maximum 2 MB · Requester And Owner Only</small></label><?php cc_check('confirmed','I am correcting the recorded facts. This request does not collect, refund or transfer money.');?><p data-cc-preview role="status"></p><div class="cc-row"><button type="submit" data-cc-submit>Submit For Owner Review</button><a class="button secondary" href="<?=access_h(cc_url($case?['id'=>$id]:[]))?>">Cancel</a></div></form></section>
